//! MIDI importer tests. Fixtures are generated by
//! `tests/fixtures/midi/make_fixtures.py`.

use cantor_io::project_file;
use cantor_io::{ImportError, MidiOpts, midi};

/// JSON snapshots with sorted map keys, so they do not depend on whether
/// serde_json's `preserve_order` feature is unified into the build.
macro_rules! assert_snapshot_sorted {
    ($($t:tt)*) => {
        insta::with_settings!({ sort_maps => true }, {
            insta::assert_json_snapshot!($($t)*);
        })
    };
}

fn fixture(name: &str) -> Vec<u8> {
    let path = format!("{}/tests/fixtures/midi/{name}", env!("CARGO_MANIFEST_DIR"));
    std::fs::read(&path).unwrap_or_else(|e| panic!("{path}: {e}"))
}

fn import_default(bytes: &[u8]) -> Result<cantor_io::Imported, ImportError> {
    midi::import(bytes, &MidiOpts::default())
}

fn snapshot_value(name: &str) -> serde_json::Value {
    let imported = midi::import(&fixture(name), &MidiOpts::default()).expect("fixture imports");
    serde_json::json!({
        "project": imported.project,
        "diagnostics": imported.diagnostics,
    })
}

#[test]
fn basic_snapshot() {
    assert_snapshot_sorted!("basic", snapshot_value("basic.mid"));
}

#[test]
fn odd_ppq_snapshot() {
    assert_snapshot_sorted!("odd_ppq", snapshot_value("odd_ppq.mid"));
}

#[test]
fn imported_projects_round_trip_through_project_files() {
    for name in ["basic.mid", "odd_ppq.mid"] {
        let imported = midi::import(&fixture(name), &MidiOpts::default()).unwrap();
        let bytes = project_file::to_bytes(&imported.project);
        let loaded = project_file::from_bytes(&bytes).unwrap();
        assert_eq!(loaded.project, imported.project, "{name}");
        assert!(
            loaded.diagnostics.is_empty(),
            "{name}: {:?}",
            loaded.diagnostics
        );
    }
}

#[test]
fn import_is_deterministic() {
    let bytes = fixture("basic.mid");
    assert_eq!(
        midi::import(&bytes, &MidiOpts::default()).unwrap(),
        midi::import(&bytes, &MidiOpts::default()).unwrap()
    );
}

#[test]
fn garbage_is_a_parse_error() {
    for bytes in [
        &b""[..],
        b"not a midi file at all",
        b"MThd\x00\x00\x00\x06\x00\x01",
    ] {
        assert!(
            matches!(
                midi::import(bytes, &MidiOpts::default()),
                Err(ImportError::Parse { .. })
            ),
            "{bytes:?}"
        );
    }
}

#[test]
fn truncated_fixtures_never_panic() {
    let bytes = fixture("basic.mid");
    for len in 0..bytes.len() {
        let _ = midi::import(&bytes[..len], &MidiOpts::default());
    }
}

/// A minimal file with the given format, division and one empty track.
fn minimal(format: u16, division: [u8; 2]) -> Vec<u8> {
    let mut b = b"MThd\x00\x00\x00\x06".to_vec();
    b.extend_from_slice(&format.to_be_bytes());
    b.extend_from_slice(&1u16.to_be_bytes());
    b.extend_from_slice(&division);
    b.extend_from_slice(b"MTrk\x00\x00\x00\x04\x00\xff\x2f\x00");
    b
}

#[test]
fn format_2_is_unsupported() {
    assert!(matches!(
        import_default(&minimal(2, [0, 96])),
        Err(ImportError::Unsupported { .. })
    ));
}

#[test]
fn timecode_timing_is_unsupported() {
    // -25 fps, 40 subframes.
    assert!(matches!(
        import_default(&minimal(0, [0xE7, 40])),
        Err(ImportError::Unsupported { .. })
    ));
}

#[test]
fn empty_file_gets_default_maps() {
    let imported = import_default(&minimal(0, [0, 96])).unwrap();
    assert!(imported.project.tracks.is_empty());
    assert_eq!(imported.project.tempo[0].bpm, 120.0);
    let codes: Vec<_> = imported
        .diagnostics
        .iter()
        .map(|d| d.code.as_str())
        .collect();
    assert_eq!(
        codes,
        [
            "midi.tempo_default",
            "midi.time_sig_default",
            "midi.no_notes"
        ]
    );
}

/// A format-0 file at 480 PPQ: one Shift-JIS lyric per note, two
/// overlapping notes on channel 0 and a drum note on channel 9.
fn lyric_file() -> Vec<u8> {
    let (ka, _, _) = encoding_rs::SHIFT_JIS.encode("か");
    let mut t: Vec<u8> = vec![0x00, 0xFF, 0x51, 3, 0x07, 0xA1, 0x20]; // 120 BPM
    t.extend([0x00, 0xFF, 0x05, ka.len() as u8]);
    t.extend(ka.iter());
    t.extend([0x00, 0x90, 60, 100]); // C4 on
    t.extend([0x00, 0x99, 36, 100]); // drum
    t.extend([0x83, 0x60, 0xFF, 0x05, 2, b'r', b'a']); // +480: lyric "ra"
    t.extend([0x00, 0x90, 62, 100]); // D4 on (C4 still sounding)
    t.extend([0x10, 0x80, 60, 0]); // C4 off
    t.extend([0x83, 0x50, 0x80, 62, 0]); // D4 off at 960
    t.extend([0x00, 0xFF, 0x2F, 0x00]);
    let mut b = b"MThd\x00\x00\x00\x06\x00\x00\x00\x01\x01\xE0MTrk".to_vec();
    b.extend((t.len() as u32).to_be_bytes());
    b.extend(t);
    b
}

#[test]
fn shift_jis_lyrics_and_monophony() {
    let imported = import_default(&lyric_file()).unwrap();
    let notes = &imported.project.tracks[0].notes;
    let got: Vec<_> = notes
        .iter()
        .map(|n| (n.start, n.length, n.key, n.lyric.as_str()))
        .collect();
    assert_eq!(got, [(0, 480, 60, "か"), (480, 480, 62, "ra")]);
    let codes: Vec<_> = imported
        .diagnostics
        .iter()
        .map(|d| d.code.as_str())
        .collect();
    assert!(codes.contains(&"midi.overlap_trimmed"), "{codes:?}");
    assert!(codes.contains(&"midi.melody"), "{codes:?}");
}

#[test]
fn channel_option_selects_the_part() {
    let opts = MidiOpts {
        track: Some(0),
        channel: Some(9),
    };
    let imported = midi::import(&lyric_file(), &opts).unwrap();
    assert_eq!(imported.project.tracks[0].notes[0].key, 36);
    let opts = MidiOpts {
        track: Some(3),
        channel: None,
    };
    assert!(matches!(
        midi::import(&lyric_file(), &opts),
        Err(ImportError::Unsupported { .. })
    ));
}
